'use strict';
const {groups,drill}=window.LESSON;
const $=id=>document.getElementById(id);
const audio=new Audio(); audio.preload='metadata';
let repeatCount=3;try{repeatCount=Math.max(2,Math.min(5,Math.round(Number(localStorage.getItem('practice.repeats'))||3)));}catch{}
const audioCache={};
async function sourceURL(which){if(location.protocol==='file:')return which;if(!audioCache[which])audioCache[which]=fetch(which).then(r=>{if(!r.ok)throw Error('音频加载失败');return r.blob()}).then(b=>URL.createObjectURL(b)).catch(e=>{delete audioCache[which];throw e});return audioCache[which];}
let mode='original',selected=0,queue=[],index=0,running=false,paused=false,phase='idle',waitLeft=0,lastFrame=0,serial=0,scope='one',played=false,taskStart=0,taskStarts=[],taskWaits=[],taskTotal=0,waitTotal=0,taskSpansSentences=false;
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cues=window.LESSON.cues||groups.map(()=>[]);
$('dialogue').innerHTML=groups.map(g=>`<article class="sentence${g.id===0?' active':''}" id="sentence-${g.id}"><div class="sentence-top"><span class="number">${String(g.id+1).padStart(2,'0')}</span><button class="sentence-button" data-sentence="${g.id}" aria-label="播放第 ${g.id+1} 句">${g.phrases.map((p,i)=>`<span class="phrase" data-phrase="${i}">${esc(p.text)}</span>`).join(' ')}</button></div>${g.zh?`<p class="translation" lang="zh-CN" hidden>${esc(g.zh)}</p>`:''}${cues[g.id].length?`<p class="cue">${cues[g.id].map(esc).join(' · ')}</p>`:''}</article>`).join('');
function focusGroup(id,n=-1,scroll=false){selected=id;$('previous').disabled=id===0;$('next').disabled=id===groups.length-1;try{localStorage.setItem('position.'+(new URLSearchParams(location.search).get('id')||'4dXbgvm4_7g'),String(id));}catch{}document.querySelectorAll('.sentence').forEach((el,i)=>el.classList.toggle('active',i===id));$('position').textContent=`${String(id+1).padStart(2,'0')} / ${String(groups.length).padStart(2,'0')}`;if(scroll){const el=$(`sentence-${id}`),rect=el.getBoundingClientRect(),bottom=document.querySelector('.player').getBoundingClientRect().top-24;if(rect.top<24||rect.bottom>bottom){const target=window.scrollY+rect.top-Math.max(24,(bottom-rect.height)/2);window.scrollTo({top:Math.max(0,target),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}}
const icons={play:'<path d="m9 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',pause:'<path d="M9 5v14M16 5v14" stroke-width="3.5"/>',prev:'<path d="M6 5v14m13-14-10 7 10 7Z"/>',next:'<path d="M18 5v14M5 5l10 7-10 7Z"/>'};
const icon=key=>`<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]}</svg>`;
function playLabel(label){$('play').innerHTML=icon(label==='暂停'?'pause':'play');$('play').setAttribute('aria-label',label);$('play').title=label;}
$('all').innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 11h10M4 16h7"/><path d="m16 14 5 3-5 3Z" fill="currentColor" stroke="none"/></svg>';$('previous').innerHTML=icon('prev');$('next').innerHTML=icon('next');playLabel('播放');

function clearHighlight(){window.ReadingTrace?.clear();document.querySelectorAll('.speaking').forEach(e=>{e.classList.remove('speaking');e.style.removeProperty('--read')});}
function progress(v){const el=document.querySelector('.progress');el.hidden=v===null;if(v===null){el.removeAttribute('aria-valuenow');return;}const p=Math.max(0,Math.min(100,v));$('progress-fill').style.transition=p===0?'none':'';$('progress-fill').style.width=p+'%';el.setAttribute('aria-valuenow',Math.round(p));}
function clipWait(i){const item=queue[i];if(!item)return 0;if(i===queue.length-1&&!$('shadow').checked&&!$('loop').checked)return 0;const next=queue[i+1];return $('shadow').checked?Math.max(.8,(item.duration-.2)*Number($('gap').value)):(mode==='drill'?(next&&next.group===item.group&&next.repeat>1?.7:1.2):.5);}
function rebuildTimeline(){taskSpansSentences=queue.some(item=>item.group!==queue[0]?.group);taskTotal=0;taskStarts=[];taskWaits=queue.map((item,i)=>{taskStarts[i]=taskTotal;const wait=i===queue.length-1&&!$('shadow').checked?0:clipWait(i);taskTotal+=item.duration+wait;return wait;});if(running&&phase==='wait'){const fraction=waitTotal?1-waitLeft/waitTotal:0;waitTotal=clipWait(index);waitLeft=waitTotal*(1-Math.max(0,Math.min(1,fraction)));}taskProgress(phase==='wait'?queue[index]?.duration||0:Math.max(0,audio.currentTime-(queue[index]?.start||0)));}
function taskProgress(local=0,complete=false){if($('loop').checked||!taskSpansSentences){progress(null);return;}const item=queue[index];const elapsed=item?(taskStarts[index]||0)+Math.min(item.duration,local)+(phase==='wait'?Math.max(0,waitTotal-waitLeft):0):taskTotal;progress(complete?100:taskTotal?elapsed/taskTotal*100:0);}
function stop(){serial++;audio.pause();running=false;paused=false;phase='idle';played=false;clearHighlight();playLabel('播放');progress(null);}
function makeQueue(id,all){if(mode==='original')return groups.filter(g=>all?g.id>=id:g.id===id).map(g=>({group:g.id,start:0,duration:g.duration,sourceStart:g.start,lead:g.lead,audioFile:g.audioFile,whole:true,repeat:1,total:1}));return drill.filter(b=>all?b.group>=id:b.group===id).flatMap(b=>Array.from({length:repeatCount},(_,i)=>({group:b.group,start:0,duration:b.duration_seconds,sourceStart:b.sourceStart,lead:b.lead,audioFile:b.audioFile,whole:b.whole,repeat:i+1,total:repeatCount})));}
function start(id,all=true){stop();scope=all?'all':'one';taskStart=id;queue=makeQueue(id,all);index=0;rebuildTimeline();running=true;playLabel('暂停');beginClip();}
async function beginClip(){const token=++serial,item=queue[index];if(!item)return finish();focusGroup(item.group,-1,true);phase='loading';played=false;$('phase').textContent='加载原声';$('status').textContent='准备播放…';$('repeat').textContent=mode==='drill'?`${item.repeat}/${item.total}`:'';taskProgress(0);try{const src=await sourceURL(item.audioFile);if(token!==serial||!running)return;if(audio.src!==new URL(src,location.href).href)audio.src=src;if(audio.readyState<2)await new Promise((resolve,reject)=>{function clean(){audio.removeEventListener('loadeddata',ok);audio.removeEventListener('error',bad)}function ok(){clean();resolve()}function bad(){clean();reject(new Error('音频加载失败'))}audio.addEventListener('loadeddata',ok,{once:true});audio.addEventListener('error',bad,{once:true});});if(token!==serial||!running)return;if(Math.abs(audio.currentTime-item.start)>.01){await new Promise(resolve=>{audio.addEventListener('seeked',resolve,{once:true});audio.currentTime=item.start;});}if(token!==serial||!running)return;await audio.play();if(token!==serial||!running)return;phase='audio';played=true;if(paused)audio.pause();$('phase').textContent=mode==='original'?'完整原句':item.whole?'整句练习':'分段练习';$('status').textContent=mode==='drill'?`第 ${item.repeat} / ${item.total} 遍`:'听原声';}catch(e){if(token!==serial)return;stop();$('phase').textContent='无法播放';$('status').textContent='请确认页面旁的音频文件存在，然后重试。';}}
function enterWait(){audio.pause();clearHighlight();const item=queue[index];phase='wait';const next=queue[index+1];waitLeft=waitTotal=clipWait(index);if(index===queue.length-1&&!$('shadow').checked&&!$('loop').checked){advance();return}phase='wait';lastFrame=performance.now();$('phase').textContent=$('shadow').checked?'轮到你跟读':'重复间隔';}
function advance(){const group=queue[index]?.group;if($('loop').checked&&group!==undefined&&queue[index+1]?.group!==group){index=queue.findIndex(item=>item.group===group);beginClip();return}index++;if(index<queue.length){beginClip();return}finish();}
function finish(){stop();$('repeat').textContent='';taskProgress(0,true);$('phase').textContent='完成';$('status').textContent='这一轮已听完，可以再练一次。';}
function frame(now){const delta=lastFrame?Math.min(.1,(now-lastFrame)/1000):0;lastFrame=now;if(running&&!paused){const item=queue[index];if(phase==='audio'&&played){const local=Math.max(0,audio.currentTime-item.start);taskProgress(local);const source=item.sourceStart+local-item.lead;groups[item.group].phrases.forEach((p,i)=>{const el=$(`sentence-${item.group}`).querySelector(`[data-phrase="${i}"]`);el.classList.toggle('speaking',source>=p.start&&source<p.end);window.ReadingTrace?.draw(el,Math.max(0,Math.min(1,(source-p.start)/(p.end-p.start))),source>=p.start&&source<p.end)});}else if(phase==='wait'){waitLeft-=delta;taskProgress(item.duration);$('status').textContent=($('shadow').checked?'跟读剩余 ':'下一遍 ')+Math.max(0,waitLeft).toFixed(1)+' 秒';if(waitLeft<=0)advance();}}document.body.classList.toggle('is-playing',running&&!paused&&phase==='audio');document.body.classList.toggle('is-shadowing',running&&!paused&&phase==='wait'&&$('shadow').checked);requestAnimationFrame(frame);}
$('dialogue').addEventListener('click',e=>{const b=e.target.closest('[data-sentence]');if(b)start(Number(b.dataset.sentence));});
function setMode(v){const resume=running,wasPaused=paused;stop();$('repeat').textContent='';mode=v;$('repeat-setting').hidden=v!=='drill';['original','drill'].forEach(id=>{$(id).classList.toggle('selected',id===v);$(id).setAttribute('aria-pressed',String(id===v))});$('hint').textContent=v==='original'?'点击句子，听原声':`分段 ${repeatCount} 遍，再整句 ${repeatCount} 遍`;$('phase').textContent='准备播放';$('status').textContent='选择一句开始';progress(null);if(resume){start(selected);paused=wasPaused;if(paused){audio.pause();playLabel('继续');}}}
$('original').onclick=()=>setMode('original');$('drill').onclick=()=>setMode('drill');
$('play').onclick=async()=>{if(!running){start(selected);return}paused=!paused;lastFrame=performance.now();playLabel(paused?'继续':'暂停');if(paused)audio.pause();else if(phase==='audio'){try{await audio.play()}catch{stop();$('status').textContent='播放受阻，请点击句子重试。';}}};
$('all').onclick=()=>start(0,true);$('previous').onclick=()=>start(Math.max(0,selected-1));$('next').onclick=()=>start(Math.min(groups.length-1,selected+1));
$('translation').onchange=()=>{document.querySelectorAll('.translation').forEach(el=>{el.hidden=!$('translation').checked;});};
$('cues').onchange=()=>document.body.classList.toggle('hide-cues',!$('cues').checked);$('shadow').onchange=()=>{document.body.classList.toggle('shadow',$('shadow').checked);$('gap-label').hidden=!$('shadow').checked;rebuildTimeline();};
$('loop').onchange=rebuildTimeline;
$('gap').onchange=rebuildTimeline;
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['BUTTON','INPUT','SELECT','TEXTAREA','A'].includes(document.activeElement.tagName)){e.preventDefault();$('play').click();}});
audio.addEventListener('ended',()=>{if(running&&phase==='audio')enterWait();});
let resume=0;try{resume=Number(localStorage.getItem('position.'+(new URLSearchParams(location.search).get('id')||'4dXbgvm4_7g')))||0;}catch{}window.addEventListener('pagehide',stop);focusGroup(Math.max(0,Math.min(groups.length-1,resume))); requestAnimationFrame(frame);

const settings=document.querySelector('.settings');
const settingsTrigger=settings.querySelector('summary');
function closeSettings(returnFocus=false){if(window.closePracticeSettings){window.closePracticeSettings(returnFocus);return;}settings.open=false;settingsTrigger.setAttribute('aria-expanded','false');if(returnFocus)settingsTrigger.focus();}
settingsTrigger.setAttribute('aria-expanded','false');
settings.addEventListener('toggle',()=>settingsTrigger.setAttribute('aria-expanded',String(settings.open)));
$('close-settings').onclick=()=>closeSettings(true);
document.addEventListener('pointerdown',event=>{if(settings.open&&!settings.contains(event.target))closeSettings();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&settings.open){event.preventDefault();closeSettings(true);}});
document.querySelectorAll('[data-gap]').forEach(button=>{button.onclick=()=>{$('gap').value=button.dataset.gap;document.querySelectorAll('[data-gap]').forEach(option=>option.setAttribute('aria-pressed',String(option===button)));rebuildTimeline();};});

function setRepeatCount(value){
 repeatCount=Math.max(2,Math.min(5,Math.round(Number(value)||3)));
 try{localStorage.setItem('practice.repeats',String(repeatCount));}catch{}
 $('drill').textContent=`Drill · ${repeatCount}×`;$('repeat-value').textContent=`${repeatCount}×`;
 document.querySelectorAll('[data-repeat]').forEach(option=>option.setAttribute('aria-pressed',String(Number(option.dataset.repeat)===repeatCount)));
 if(mode==='drill'&&running){const current=queue[index];const updated=makeQueue(taskStart,scope==='all');const nextIndex=updated.findIndex(item=>item.audioFile===current.audioFile&&item.whole===current.whole&&item.repeat===Math.min(current.repeat,repeatCount));if(nextIndex>=0){queue=updated;index=nextIndex;$('repeat').textContent=`${queue[index].repeat}/${repeatCount}`;rebuildTimeline();}}
}
$('repeat-toggle').onclick=()=>{const expanded=$('repeat-options').hidden;$('repeat-options').hidden=!expanded;$('repeat-toggle').setAttribute('aria-expanded',String(expanded));};
document.querySelectorAll('[data-repeat]').forEach(option=>option.onclick=()=>{setRepeatCount(option.dataset.repeat);$('repeat-options').hidden=true;$('repeat-toggle').setAttribute('aria-expanded','false');$('repeat-toggle').focus();});
setRepeatCount(repeatCount);

progress(null);
